/* ============================================================
   موسوعة الأدوية — أجسام بطاقات دفعة الإنجاب ومنع الحمل (repro1)
   rx/rx-repro1.js   (يُحمَّل عند فتح البطاقة)
   ⚠️ محتوى تثقيفي عام وليس وصفة علاج. الجرعة والمقاس ومواعيد
   التركيب والتبديل يحدّدها طبيب أو قابلة أو صيدلي.
   ============================================================ */

var RX_BODY = window.RX_BODY || {};

RX_BODY['norethisterone-enantate'] = {
  what: {
    ar: 'النوريثيستيرون إينانتات محلول زيتي يحتوي هرموناً بروجستينياً، يُحقن في العضل ويُعطى في العيادة لا في البيت. الهرمون في الحقنة موجود بصورة مُستَرة بطيئة، فبعد الحقن يتحلّل شيئاً فشيئاً إلى نوريثيستيرون الفعّال، ولهذا يبقى أثره ممتداً بعد الحقنة الواحدة ولا يحتاج صاحبته إلى تذكّر شيء كل يوم. وهو موصوف في نشرته وسيلةً قصيرة المدى لا وسيلة عمر، ولا يحمي من العدوى المنقولة جنسياً بحال، فمن أرادها احتاج الواقي معه.',
    en: 'Norethisterone enantate is an oily solution containing a progestogen hormone, injected into muscle and given in a clinic rather than at home. The hormone is present as a slow ester, so after the injection it is gradually broken down into active norethisterone, which is why one injection keeps working for a stretch of time and the user has nothing to remember daily. Its own leaflet describes it as a short-term method rather than a lifelong one, and it gives no protection at all against sexually transmitted infection, so anyone wanting that needs a condom alongside it.'
  },
  why: {
    ar: 'يُوصف لمنع الحمل حين تُطلب حماية موثوقة لفترة محدودة، ومن أمثلته المكتوبة في النشرة: المدّة التي يحتاجها قطع القناة المنوية عند الزوج حتى يصير مأموناً، والفترة التي يجب فيها تجنّب الحمل بعد تطعيم الحصبة الألمانية. ويناسب كذلك من لا تستطيع تناول حبوب يومية أو لا ترغب فيها. ومن مزاياه المذكورة أنه عالي الفعالية، ولا يتطلّب تذكّراً يومياً بعد أخذه، ولا يتدخّل في العلاقة الزوجية ولا يقطعها.',
    en: 'It is prescribed to prevent pregnancy when reliable cover is needed for a limited period. The examples written into the leaflet include the time a husband’s vasectomy needs before it can be relied on, and the period during which pregnancy must be avoided after a rubella vaccination. It also suits a woman who cannot take a daily tablet or does not wish to. Among the advantages it lists are that it is highly effective, that nothing has to be remembered day by day once it has been given, and that it does not interrupt or interfere with intercourse.'
  },
  how: {
    ar: 'يعمل بثلاث طرق تتغيّر أوزانها مع مرور الوقت بعد الحقنة. في أولها يمنع الإباضة، أي يوقف خروج البويضة من المبيض فلا يكون هناك ما يُلقّح أصلاً. ثم مع اقتراب موعد الجرعة التالية يصير عمله موضعياً في أغلبه: يُثخّن مخاط عنق الرحم فيصير حاجزاً لزجاً يمنع صعود الحيوانات المنوية إلى داخل الرحم، ويرقّق بطانة الرحم فتصير أقلّ تهيّؤاً لاستقبال بويضة ملقّحة. ومن هذا الترتيب يُفهم لماذا لا يجوز تأخير الموعد المتّفق عليه مع مقدّم الرعاية.',
    en: 'It works in three ways whose weight shifts as time passes after the injection. At first it prevents ovulation, that is it stops the egg leaving the ovary so there is nothing to be fertilised at all. Then, as the time for the next dose approaches, its action becomes mostly local: it thickens the mucus of the cervix into a sticky barrier that stops sperm climbing into the womb, and it thins the lining of the womb so it is less ready to receive a fertilised egg. From that sequence it becomes clear why the appointment agreed with the provider should not be allowed to slip.'
  },
  effects: {
    ar: 'أكثر ما يُشتكى منه تغيّر نمط النزف: تبقيع بين الدورات، أو دورات غير منتظمة، أو انقطاع الطمث كلّه، وهذا في ذاته ليس علامة خطر. ويأتي كذلك انتفاخ البطن، وشدّ الثديين وإيلامهما، وصداع، ودوخة، وغثيان، وزيادة في الوزن. وقد تظهر عند موضع الحقن نفسه آلام أو حكّة أو تهيّج. وتُذكر في النشرة تقلّبات المزاج والشعور بالاكتئاب بين آثاره، وهي ليست أمراً يُتجاوز عنه بل يُعرض على الطبيب لأن الاكتئاب قد يشتدّ.',
    en: 'What is complained of most is a change in the bleeding pattern: spotting between periods, irregular periods, or periods stopping altogether, and that in itself is not a danger sign. There may also be bloating, tight and tender breasts, headache, dizziness, nausea and weight gain. At the injection site itself there can be pain, itching or irritation. The leaflet lists mood swings and depressed mood among its effects, and this is not something to be waved away but to be shown to a doctor, because depression can become severe.'
  },
  warning: {
    ar: 'اطلب الطوارئ فوراً عند علامة جلطة: ألم أو تورّم في ساق واحدة، أو ألم في الصدر أو وخز يشتدّ مع الشهيق، أو ضيق نفس، أو سعال مفاجئ بلا سبب أو مع دم، أو صداع شديد جديد أو صداع نصفي يشتدّ، أو تغيّر مفاجئ في البصر أو السمع أو النطق، أو ضعف أو خدر في طرف، أو دوخة شديدة أو إغماء. واذهب فوراً كذلك عند اصفرار الجلد أو بياض العين، أو ألم شديد في أعلى البطن، أو حكّة عامة في الجسم. وتورّم الوجه أو الشفتين أو اللسان أو الحلق طوارئ لا تحتمل الانتظار. وإن جاءتك أفكار إيذاء النفس مع تدهور المزاج فاطلب المساعدة اليوم لا غداً.',
    en: 'Get emergency help at once for any sign of a clot: pain or swelling in one leg, chest pain or a stabbing pain that worsens on breathing in, shortness of breath, a sudden unexplained cough or coughing blood, a new severe headache or a worsening migraine, a sudden change in sight, hearing or speech, weakness or numbness in a limb, severe dizziness or fainting. Go immediately too if the skin or the whites of the eyes turn yellow, if there is severe pain in the upper abdomen, or generalised itching of the body. Swelling of the face, lips, tongue or throat is an emergency that cannot wait. And if thoughts of self-harm come with a sinking mood, seek help today, not tomorrow.'
  },
  interact: {
    ar: 'تُضعف فعاليته أدوية تُسرّع تكسيره في الكبد، وأبرزها في نشرته: الباربيتورات، وبعض أدوية الصرع، ومضادات حيوية معيّنة، وغريزيوفولفين المضاد للفطريات، وفينيل بوتازون، ومثبّطات البروتياز المستعملة في فيروس نقص المناعة والتهاب الكبد سي، وعشبة سانت جون. ومن كان على واحد منها احتاج وسيلة إضافية يتّفق عليها مع طبيبه. وقد يغيّر هو بدوره حاجة مريض السكّري إلى الأنسولين أو أقراص السكّر فتلزم متابعة. وأخبر الجرّاح والمختبر أنك تأخذينه قبل أي عملية أو تحليل.',
    en: 'Its effectiveness is weakened by medicines that speed its breakdown in the liver, chiefly, as its leaflet lists them: barbiturates, some epilepsy drugs, certain antibiotics, the antifungal griseofulvin, phenylbutazone, the protease inhibitors used in HIV and hepatitis C, and St John’s wort. Anyone on one of these needs an additional method agreed with their doctor. It may in turn change how much insulin or how many diabetes tablets a diabetic patient needs, so monitoring is required. And tell the surgeon and the laboratory that you are using it before any operation or blood test.'
  },
  avoid: {
    ar: 'لا يُستعمل في الحمل أو عند الشكّ فيه. ولا لمن عنده جلطة الآن أو سبقته جلطة في وريد أو رئة، ولا لمن أصابته جلطة قلبية أو سكتة دماغية. ويُمنع مع مرض الكبد الشديد أو اختلال وظائفه أو أورامه، ومع الأورام المعتمدة على الهرمونات كسرطان الثدي وسرطان بطانة الرحم، ومع البورفيريا، ومع السكّري الشديد المؤذي للأوعية، ومع ارتفاع الضغط الشديد، ومع اضطراب دهون الدم، ومع الحساسية لأي من مكوّناته. وفي الرضاعة تصل كميات ضئيلة إلى الحليب ولا يُعرف لها أذى في الرضيع السليم، لكنه يُتجنّب إذا كان الرضيع مصاباً بيرقان شديد أو ممتدّ يحتاج علاجاً.',
    en: 'It is not used in pregnancy or when pregnancy is suspected. Nor by anyone who has a clot now or has had one in a vein or the lung, or who has had a heart attack or a stroke. It is contraindicated with severe liver disease, deranged liver function or liver tumours, with hormone-dependent cancers such as breast cancer and cancer of the womb lining, with porphyria, with severe diabetes that has damaged the blood vessels, with severe high blood pressure, with disorders of blood fats, and with allergy to any of its ingredients. In breastfeeding, tiny amounts reach the milk and are not known to harm a healthy baby, but it is avoided if the baby has severe or prolonged jaundice needing treatment.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.medicines.org.uk/emc/product/1134/pil',
    'https://www.medicines.org.uk/emc/product/1134/smpc'
  ]
};

RX_BODY['levonorgestrel-releasing-implant'] = {
  what: {
    ar: 'شريحة الليفونورجستريل قضيبان صغيران مرنان من السيليكون يحتويان هرموناً بروجستينياً، يزرعهما مدرَّب تحت جلد أعلى الذراع بتخدير موضعي بعد شقّ صغير، ويُخرجهما بالطريقة نفسها. وهي من الوسائل طويلة الأمد العكوسة، أي أن الخصوبة تعود بعد إخراجها. صُمّمت بقضيبين بدل الست القديمة لتسهيل التركيب والإخراج مع بقاء مستوى الهرمون في الدم كما هو. ولا تحمي من العدوى المنقولة جنسياً.',
    en: 'The levonorgestrel implant is two small flexible silicone rods containing a progestogen hormone, placed by a trained provider under the skin of the upper arm under local anaesthetic through a small incision, and taken out the same way. It is a long-acting reversible method, meaning fertility returns after it is removed. It was designed with two rods instead of the older six to make insertion and removal easier while keeping the hormone level in the blood the same. It gives no protection against sexually transmitted infection.'
  },
  why: {
    ar: 'تُستعمل لمنع الحمل لفترة ممتدّة يحدّدها نوعها ومقدّم الرعاية، وتناسب من تريد حماية عالية بلا حبّة يومية ولا موعد شهري ولا شيء يُتذكّر عند كل علاقة. وهي مفيدة خاصة لمن جرّبت الحبوب ونسيتها، أو لمن يشقّ عليها تكرار زيارات العيادة. وتذكر نشرتها أنها متوافقة مع الرضاعة ولا يُعرف لها أذى على الجنين إن حدث تعرّض غير مقصود. وليست علاجاً لمرض، بل وسيلة تنظيم إنجاب تُختار بالموازنة بين راحتها وآثارها على نمط النزف.',
    en: 'It is used to prevent pregnancy for an extended period decided by its type and the provider, and it suits a woman who wants high protection with no daily tablet, no monthly appointment and nothing to remember at the time of intercourse. It is particularly useful for someone who has tried pills and forgotten them, or who finds repeated clinic visits difficult. Its leaflet states that it is compatible with breastfeeding and that no fetal harm is known from inadvertent exposure. It is not a treatment for a disease but a family-planning method, chosen by weighing its convenience against its effects on the bleeding pattern.'
  },
  how: {
    ar: 'يخرج الهرمون من القضيبين ببطء ثابت إلى الدم، ثم يعمل بثلاث طرق مجتمعة. أولها كبح موجة الهرمون المُلَوتِن التي يطلقها الجسم لتفجير الجُريب، وبكبحها لا تُطلق البويضة. وثانيها تغيير مخاط عنق الرحم فيصير ثخيناً معادياً للحيوانات المنوية يمنع مرورها. وثالثها تغيير بطانة الرحم فتصير غير مهيّأة لاستقبال بويضة ملقّحة. ولأن العمل مستمرّ ما دام القضيبان في مكانهما، فالحماية لا تعتمد على انتظام الاستعمال ولا على تذكّر صاحبتها.',
    en: 'The hormone leaves the two rods slowly and steadily into the blood, then works in three combined ways. The first is to suppress the surge of luteinising hormone that the body releases to burst the follicle; with that suppressed, no egg is released. The second is to change the cervical mucus so it becomes thick and hostile to sperm, blocking their passage. The third is to change the lining of the womb so it is not prepared to receive a fertilised egg. Because the action continues as long as the rods are in place, protection does not depend on regular use or on the user remembering anything.'
  },
  effects: {
    ar: 'أشهر أثر لها هو اختلال نمط الطمث: تبقيع، أو نزف متطاول، أو دورات متقاربة، أو انقطاع كامل — وهذا سبب الإخراج الأول عند كثيرات. وتُذكر كذلك صداع، وعصبية، ودوخة، وغثيان، وحبّ شباب أو تغيّر في الشعر، وشدّ الثديين، وتغيّر الوزن، وألم بطن، وتقلّبات مزاج أو اكتئاب، وارتفاع في ضغط الدم، وتفاعل جلدي عند موضع الزرع. وقد تتكوّن كيسات مبيضية وظيفية صغيرة تزول من نفسها غالباً بلا تدخّل.',
    en: 'Its best known effect is disruption of the menstrual pattern: spotting, prolonged bleeding, closely spaced periods, or complete cessation, and this is the leading reason for early removal in many women. Also reported are headache, nervousness, dizziness, nausea, acne or changes in the hair, breast tenderness, weight change, abdominal pain, mood swings or depression, a rise in blood pressure, and a skin reaction at the implant site. Small functional ovarian cysts may form and usually disappear on their own without any intervention.'
  },
  warning: {
    ar: 'اذهبي فوراً إذا اصفرّ الجلد أو بياض العين، فاليرقان أو التهاب الكبد الركودي يوجب إخراج الشريحة. واطلبي الطوارئ عند علامة جلطة: ألم أو تورّم في ساق، أو ألم صدر، أو ضيق نفس، أو ضعف مفاجئ في طرف أو اضطراب نطق أو بصر. وألم شديد أسفل البطن مع تأخّر الدورة يستوجب استبعاد حمل خارج الرحم اليوم لا لاحقاً. واعرضي على طبيبك سريعاً أي تدهور في المزاج أو أفكار إيذاء النفس. وإن لم تعودي تحسّين القضيبين تحت جلدك، أو رأيت ألماً أو نزفاً أو احمراراً أو خدراً في موضعهما، فاطلبي موعداً قريباً لأن الحماية قد تكون سقطت.',
    en: 'Go at once if the skin or the whites of the eyes turn yellow, as jaundice or cholestatic hepatitis means the implant must be removed. Seek emergency help for any sign of a clot: pain or swelling in a leg, chest pain, breathlessness, sudden weakness in a limb, or disturbed speech or vision. Severe lower abdominal pain with a late period calls for an ectopic pregnancy to be excluded today, not later. Show any worsening of mood or thoughts of self-harm to your doctor quickly. And if you can no longer feel the two rods under your skin, or notice pain, bleeding, redness or numbness where they sit, book an early appointment, because your protection may have lapsed.'
  },
  interact: {
    ar: 'تُضعف حمايتها الأدوية التي تُحرّض إنزيمات الكبد فتُسرّع تكسير الهرمون، ومنها ريفامبيسين المستعمل في السلّ، وبعض أدوية الصرع مثل كاربامازيبين والفينوباربيتال، وعشبة سانت جون. ومن اضطرّ إلى واحد منها لزمه وسيلة إضافية كالواقي طوال المدّة وبعدها بفترة يحدّدها الطبيب، وقد يُنصح ببديل آخر كلّياً إن كان الدواء دائماً. وأخبري أي طبيب يصف لك دواءً جديداً أن عندك شريحة، فهذا التعارض صامت لا يُحسّ به إلا بحمل غير متوقّع.',
    en: 'Its protection is weakened by medicines that induce liver enzymes and so speed the breakdown of the hormone, among them rifampicin used in tuberculosis, some epilepsy drugs such as carbamazepine and phenobarbital, and St John’s wort. Anyone who must take one of these needs an additional method such as a condom throughout and for a period afterwards set by the doctor, and a completely different method may be advised if the drug is permanent. Tell any doctor prescribing you something new that you have an implant, because this interaction is silent and is only felt as an unexpected pregnancy.'
  },
  avoid: {
    ar: 'لا تُستعمل في الحمل أو عند الشكّ فيه، ولا مع سرطان الثدي الحالي أو السابق، ولا مع نزف مهبلي غير مشخّص قبل معرفة سببه، ولا مع مرض كبدي شديد أو أورام الكبد الحميدة أو الخبيثة، ولا مع جلطة قائمة أو اضطراب تخثّري نشط. وتُخرج فوراً إذا ظهر مرض تخثّري أو اشتُبه فيه، أو ظهر يرقان. وتحتاج مراقبة أشدّ من عندها ارتفاع في ضغط الدم أو تاريخ اكتئاب أو سبق لها حمل خارج الرحم. وفي الرضاعة تُعدّ متوافقة بحسب نشرتها. ولا تُغني عن الواقي لمن يحتاج وقاية من العدوى.',
    en: 'It is not used in pregnancy or when pregnancy is suspected, nor with current or past breast cancer, nor with undiagnosed vaginal bleeding before its cause is known, nor with severe liver disease or benign or malignant liver tumours, nor with an existing clot or an active clotting disorder. It must be removed at once if thrombotic disease appears or is suspected, or if jaundice develops. Closer monitoring is needed for anyone with raised blood pressure, a history of depression, or a previous ectopic pregnancy. In breastfeeding it is considered compatible according to its leaflet. It does not replace a condom for anyone needing protection from infection.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.accessdata.fda.gov/drugsatfda_docs/label/2016/020544s010lbl.pdf',
    'https://www.medsafe.govt.nz/profs/datasheet/j/jadelleimplant.pdf',
    'https://www.ncbi.nlm.nih.gov/books/NBK539737/'
  ]
};

RX_BODY['etonogestrel-releasing-implant'] = {
  what: {
    ar: 'شريحة الإيتونوجستريل قضيب واحد صغير مرن يحتوي هرموناً بروجستينياً، يوضع تحت جلد أعلى الذراع الداخلي بواسطة مدرَّب معتمد، ويُخرج بالطريقة نفسها. وهي وسيلة طويلة الأمد عكوسة، تُصرف في بعض البلاد ضمن برنامج مقيّد لأن التركيب والإخراج نفسيهما يحملان خطراً إن أُسيء أداؤهما. ويحتوي بعض أنواعها مادة ظليلة للأشعة تُعين على تحديد موضعها إن لم تُحسّ باليد. وتقول نشرتها صراحة إنها لا تحمي من العدوى المنقولة جنسياً ولا من فيروس نقص المناعة.',
    en: 'The etonogestrel implant is a single small flexible rod containing a progestogen hormone, placed under the skin of the inner upper arm by a certified trained provider and removed the same way. It is a long-acting reversible method, supplied in some countries under a restricted programme because the insertion and removal themselves carry risk if done badly. Some versions contain a radiopaque substance that helps locate it if it cannot be felt by hand. Its leaflet states plainly that it does not protect against sexually transmitted infection or against HIV.'
  },
  why: {
    ar: 'تُستعمل لمنع الحمل وحده، وتناسب من تريد حماية مستمرّة بلا حبّة يومية ولا شيء يُفعل وقت العلاقة، ومن يشقّ عليها الالتزام بمواعيد متكرّرة. وميزتها العملية أن قضيبها واحد فقط فتركيبها وإخراجها أبسط، وأن أثرها ينتهي بإخراجها فتعود الخصوبة. وهي خيار كثير التداول لمن أرادت وسيلة خالية من الإستروجين، ومن ثمّ تُطرح أحياناً على من لا تصلح لها الوسائل المحتوية عليه. وليست علاجاً لمرض ولا تُوصف لغرض آخر في نشرتها الرسمية، وأي منفعة أخرى تُلاحظ معها فهي عرَض لا هدف.',
    en: 'It is used for contraception alone, and suits a woman who wants continuous protection with no daily tablet and nothing to do at the time of intercourse, or who finds repeated appointments hard to keep. Its practical advantage is that there is only one rod, so insertion and removal are simpler, and that its effect ends when it is taken out, so fertility returns. It is a widely used option for anyone wanting a method free of oestrogen, and so it is sometimes offered to women for whom oestrogen-containing methods are unsuitable. It is not a treatment for a disease and is not prescribed for any other purpose in its official leaflet; any other benefit noticed with it is incidental rather than intended.'
  },
  how: {
    ar: 'يخرج الهرمون من القضيب بمعدّل ثابت بطيء، وأصل عمله منع الإباضة، أي منع خروج البويضة من المبيض فلا يكون ثمّة ما يُلقَّح. ويضاف إلى ذلك تثخين مخاط عنق الرحم حتى يصير حاجزاً يمنع صعود الحيوانات المنوية، وتغيير بطانة الرحم فتقلّ تهيّؤها لغرس بويضة ملقّحة. ولأن الهرمون يخرج من مستودع مزروع لا من قرص يُبتلع، فالحماية لا تتأثّر بقيء ولا إسهال ولا نسيان، وهذا سبب اعتمادها العالي.',
    en: 'The hormone leaves the rod at a slow steady rate, and its basic action is to prevent ovulation, that is to stop the egg leaving the ovary so there is nothing to fertilise. Added to this is thickening of the cervical mucus until it becomes a barrier that stops sperm climbing, and a change in the lining of the womb that makes it less ready for a fertilised egg to implant. Because the hormone comes from an implanted reservoir rather than a swallowed tablet, protection is unaffected by vomiting, diarrhoea or forgetting, and that is why it is so dependable.'
  },
  effects: {
    ar: 'أوّل ما تلاحظه المستعملة تغيّر نمط الطمث، ويشمل التبقيع والنزف غير المنتظم وانقطاع الدورة، وهو أشهر ما يدفع إلى إخراجها. وتُذكر كذلك صداع، وحبّ شباب، وشدّ الثديين وإيلامهما، وتهيّج أو تورّم مهبلي، وزيادة في الوزن، وصعوبة نوم، وإرهاق، وتقلّب مزاج. وأغلب هذه يخفّ مع الأشهر الأولى، لكنه يستحقّ أن يُذكر للطبيب لا أن يُحتمل صامتاً، لأن بعضه له بدائل أو تدبير. وانقطاع الطمث معها ليس علامة مرض ولا يعني أن شيئاً تجمّع في الداخل.',
    en: 'The first thing users notice is a change in the menstrual pattern, including spotting, irregular bleeding and periods stopping, and this is the commonest reason for having it removed. Also reported are headache, acne, tight and tender breasts, vaginal irritation or swelling, weight gain, difficulty sleeping, tiredness and mood swings. Most of these ease over the first months, but they deserve to be mentioned to the doctor rather than borne in silence, because some of them have alternatives or can be managed. Periods stopping with it is not a sign of illness and does not mean anything has built up inside.'
  },
  warning: {
    ar: 'تحسّسي القضيب تحت جلدك، وإن لم تجديه أو أحسست أنه انكسر أو انثنى فأخبري مقدّم الرعاية فوراً — فقد يكون قد هاجر، وقد وُصف انتقاله إلى أوعية الصدر. واطلبي الطوارئ عند ألم صدر أو ضيق نفس أو سعال أو نفث دم، وعند ألم ساق أو صداع شديد مفاجئ أو تغيّر مفاجئ في البصر أو ضعف أو خدر في طرف أو اضطراب في النطق. واذهبي فوراً عند اصفرار الجلد أو بياض العين، أو ألم أو تورّم أسفل البطن، أو نزف طمثي غزير يطول أكثر من أسبوع، أو كتلة جديدة في الثدي. وأي ألم أو نزف أو احمرار أو حرقان أو خدر عند موضع الزرع يُعرض ولا يُهمل.',
    en: 'Feel for the rod under your skin, and if you cannot find it or it feels broken or bent, tell your provider at once, as it may have migrated; movement into the vessels of the chest has been described. Seek emergency help for chest pain, breathlessness, cough or coughing blood, and for leg pain, a sudden severe headache, a sudden change in vision, weakness or numbness in a limb, or disturbed speech. Go immediately for yellowing of the skin or the whites of the eyes, pain or swelling in the lower abdomen, unusually heavy menstrual bleeding lasting more than a week, or a new lump in the breast. Any pain, bleeding, redness, burning or numbness at the implant site must be shown, not ignored.'
  },
  interact: {
    ar: 'تُضعف حمايتها الأدوية والأعشاب التي تُسرّع تكسير الهرمون في الكبد، وتُذكر عشبة سانت جون بالاسم في نشرتها، ومعها من الفصيلة نفسها ريفامبيسين وبعض أدوية الصرع. وقد ثبت فشل الشريحة فعلياً عند من كانت تأخذ ريفامبيسين. فمن وُصف له واحد من هذه احتاج وسيلة إضافية طوال المدّة وبعدها بفترة يحدّدها الطبيب. وليس بينها وبين الأطعمة تعارض يُذكر. والقاعدة العملية: أخبري كل من يصف لك دواءً جديداً أن عندك شريحة قبل أن يكتبه.',
    en: 'Its protection is weakened by medicines and herbs that speed the breakdown of the hormone in the liver; St John’s wort is named in its leaflet, and with it, from the same family, rifampicin and some epilepsy drugs. Actual failure of the implant has been documented in a woman taking rifampicin. Anyone prescribed one of these needs an additional method throughout and for a period afterwards set by the doctor. There is no notable interaction with foods. The practical rule is to tell anyone prescribing you a new medicine that you have an implant before they write it.'
  },
  avoid: {
    ar: 'لا تُستعمل مع الحمل أو الشكّ فيه، ولا مع جلطة قائمة أو سابقة في الساق أو الرئة أو العين، ولا مع سابقة سكتة دماغية، ولا مع سرطان الثدي، ولا مع سرطان الكبد أو مرض كبدي، ولا مع نزف مهبلي غير مفسَّر، ولا مع بعض اضطرابات النزف. ونشرتها لا توصي بها أثناء الرضاعة. وتحتاج نقاشاً خاصاً قبلها من عندها اكتئاب أو ضغط مرتفع أو سبق لها حمل خارج الرحم. والقاعدة التي لا تُنسى: هي تمنع الحمل ولا تمنع العدوى، فمن احتاج الوقاية من الأمراض المنقولة جنسياً استعمل الواقي معها.',
    en: 'It is not used with pregnancy or suspected pregnancy, nor with a current or past clot in the leg, lung or eye, nor with a previous stroke, nor with breast cancer, nor with liver cancer or liver disease, nor with unexplained vaginal bleeding, nor with certain bleeding disorders. Its leaflet does not recommend it during breastfeeding. A special discussion is needed beforehand for anyone with depression, raised blood pressure or a previous ectopic pregnancy. And the rule not to forget: it prevents pregnancy and not infection, so anyone needing protection from sexually transmitted disease uses a condom alongside it.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a625057.html',
    'https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=487f8a62-e142-457c-97cc-2e398fde7594'
  ]
};

RX_BODY['levonorgestrel-releasing-intrauterine-system'] = {
  what: {
    ar: 'اللولب الهرموني جهاز بلاستيكي صغير على شكل حرف تي يحمل مستودعاً من هرمون بروجستيني، يركّبه طبيب أو قابلة داخل الرحم عبر عنقه، وله خيطان رفيعان يتدلّيان قليلاً في المهبل يُستدلّ بهما على بقائه في مكانه ويُسحب بهما عند الإخراج. يعمل موضعياً في أغلبه فيصل من الهرمون إلى الدم قدر يسير مقارنةً بالحبوب. وهو وسيلة طويلة الأمد عكوسة، أي أن الخصوبة تعود بعد إخراجه بلا فترة انتظار. ولا يحمي من العدوى المنقولة جنسياً.',
    en: 'The hormonal coil is a small T-shaped plastic device carrying a reservoir of a progestogen hormone, fitted by a doctor or midwife inside the womb through the cervix, with two fine threads hanging a little into the vagina by which its position is checked and by which it is pulled out. It works mostly locally, so only a small amount of hormone reaches the blood compared with tablets. It is a long-acting reversible method, meaning fertility returns after removal with no waiting period. It gives no protection against sexually transmitted infection.'
  },
  why: {
    ar: 'يُستعمل لمنع الحمل، وبعض أنواعه مرخّص أيضاً لعلاج غزارة الطمث لأنه يرقّق بطانة الرحم فيقلّ النزف حتى ينقطع عند كثيرات. ويُستعمل خارج الترخيص في فرط تنسّج بطانة الرحم، وفي بطانة الرحم المهاجرة، وفي العضال الغدّي الرحمي، حيث يُطلب أثره الموضعي على البطانة نفسها. ولهذا صار عند كثير من النساء وسيلتين في واحدة: منع حمل من جهة، وعلاج نزف مرهق أو ألم شهري من جهة أخرى، وهذا ما يجعله مطروحاً حتى على من لا تطلب منع الحمل أصلاً.',
    en: 'It is used to prevent pregnancy, and some brands are also licensed to treat heavy menstrual bleeding, because it thins the lining of the womb so bleeding decreases and in many women stops altogether. It is used off-label in endometrial hyperplasia, in endometriosis and in adenomyosis, where its local effect on the lining itself is what is wanted. For many women it therefore becomes two methods in one: contraception on one side, and treatment of exhausting bleeding or monthly pain on the other, which is why it is offered even to women who are not asking for contraception at all.'
  },
  how: {
    ar: 'يطلق اللولب الهرمون داخل تجويف الرحم مباشرةً، فيعمل بثلاث طرق. أولاها ترقيق بطانة الرحم حتى تصير رقيقة لا تصلح لغرس بويضة ملقّحة، وهي نفسها التي تُنقص النزف الشهري. وثانيتها تثخين مخاط عنق الرحم فيصير حاجزاً يمنع مرور الحيوانات المنوية إلى الداخل. وثالثتها أن الإباضة نفسها قد تُمنع عند بعض النساء لا كلّهنّ، فكثيرات يبقى مبيضهنّ يعمل بينما الحماية قائمة بالطريقتين الأوليين.',
    en: 'The coil releases the hormone directly inside the cavity of the womb, and works in three ways. The first is thinning the lining of the womb until it is too thin for a fertilised egg to implant, and it is this same effect that reduces monthly bleeding. The second is thickening the mucus of the cervix into a barrier that stops sperm passing inside. The third is that ovulation itself may be prevented in some women but not all, so in many the ovary keeps working while protection rests on the first two mechanisms.'
  },
  effects: {
    ar: 'أشهر ما يحدث تغيّر نمط الطمث: تبقيع ونزف غير منتظم في الأشهر الأولى، ثم دورات أخفّ كثيراً أو انقطاع تامّ عند كثيرات، والانقطاع هنا ليس علامة مرض. ويُذكر كذلك صداع، وحبّ شباب، وشدّ الثديين، وغثيان، وزيادة وزن، ومغص رحمي، وتقلّب مزاج، وتساقط شعر. وقد تتكوّن كيسات مبيضية غالباً ما تزول وحدها. وتُذكر مع هذه الفصيلة تقارير عن اكتئاب وهبوط مزاج تستحقّ العرض على الطبيب لا الصبر عليها. وأغلب هذه الآثار تخفّ بعد الأشهر الأولى.',
    en: 'The commonest thing is a change in the menstrual pattern: spotting and irregular bleeding in the first months, then far lighter periods or complete cessation in many women, and here the cessation is not a sign of illness. Also reported are headache, acne, breast tenderness, nausea, weight gain, uterine cramping, mood swings and hair loss. Ovarian cysts may form and usually resolve on their own. Reports of depression and low mood are described with this class of medicine and deserve to be shown to a doctor rather than endured. Most of these effects ease after the first months.'
  },
  warning: {
    ar: 'اطلبي الطوارئ عند ألم حوضي شديد أو مفاجئ، خصوصاً مع تأخّر الدورة أو نزف غير معتاد، لأن الحمل خارج الرحم احتمال قائم وهو حالة خطرة. واذهبي فوراً عند إفراز مهبلي كريه الرائحة، أو حمّى وقشعريرة أو أعراض شبيهة بالإنفلونزا، أو ألم عند الجماع أو قروح تناسلية، فهذه علامات التهاب الحوض. وألم صدر أو كتف ساحق يستوجب الإسعاف. واذهبي كذلك إن غاب الخيطان أو صارا أطول أو أقصر أو لمست اللولب نفسه، فقد يكون نزل أو خرج أو اخترق الجدار. ونزف غزير أو مطوّل جديد يُعرض على الطبيب لا يُنتظر.',
    en: 'Seek emergency care for severe or sudden pelvic pain, especially with a late period or unusual bleeding, because ectopic pregnancy remains possible and is dangerous. Go immediately for foul-smelling vaginal discharge, fever and chills or flu-like symptoms, pain during intercourse or genital sores, as these are signs of pelvic infection. Crushing chest or shoulder pain needs an ambulance. Go too if the threads disappear, become longer or shorter, or you can feel the device itself, as it may have slipped, been expelled or perforated the wall. New heavy or prolonged bleeding is shown to a doctor rather than waited out.'
  },
  interact: {
    ar: 'لأن عمله موضعيّ في أغلبه فتعارضاته الدوائية أقلّ من الوسائل التي تُبتلع، غير أن الأدوية المحرّضة لإنزيمات الكبد — كريفامبيسين وكاربامازيبين والفينوباربيتال وعشبة سانت جون — معروفة بأنها تُسرّع تكسير هذه الفصيلة من الهرمونات، فيُناقَش أمرها مع الطبيب عند وصفها. ولا يمنع اللولب أخذ المضادات الحيوية المعتادة ولا مسكّنات الدورة. والأهمّ عملياً: أخبري أي طبيب أو مسعف أو أخصائي أشعة أن عندك لولباً قبل أي إجراء داخل الرحم.',
    en: 'Because its action is mostly local, its drug interactions are fewer than with swallowed methods, though medicines that induce liver enzymes, such as rifampicin, carbamazepine, phenobarbital and St John’s wort, are known to speed the breakdown of this family of hormones, so they should be discussed with the doctor when prescribed. The coil does not prevent taking ordinary antibiotics or period painkillers. Most important in practice: tell any doctor, paramedic or imaging specialist that you have a coil before any procedure inside the womb.'
  },
  avoid: {
    ar: 'لا يُركّب مع الحمل أو الشكّ فيه، ولا مع التهاب حوض قائم أو التهاب في عنق الرحم، ولا مع عدوى تناسلية غير معالَجة، ولا مع نزف مهبلي غير مفسَّر قبل معرفة سببه، ولا مع تشوّه في تجويف الرحم يمنع استقراره، ولا مع اشتباه سرطان في الرحم أو عنقه. ويُمنع مع مرض كبدي شديد ومع الحساسية لمكوّناته، ويُتجنّب مع سرطان الثدي. ومن سبق لها حمل خارج الرحم أو التهاب حوض متكرّر تحتاج نقاشاً خاصاً. ولا يُغني عن الواقي لمن يحتاج وقاية من العدوى المنقولة جنسياً.',
    en: 'It is not fitted with pregnancy or suspected pregnancy, nor with active pelvic infection or inflammation of the cervix, nor with an untreated genital infection, nor with unexplained vaginal bleeding before its cause is known, nor with a distortion of the uterine cavity that prevents it sitting properly, nor with suspected cancer of the womb or cervix. It is contraindicated with severe liver disease and with allergy to its components, and is avoided with breast cancer. Anyone with a previous ectopic pregnancy or repeated pelvic infection needs a special discussion. It does not replace a condom for those needing protection from infection.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a613047.html',
    'https://www.ncbi.nlm.nih.gov/books/NBK539737/',
    'https://medlineplus.gov/ency/patientinstructions/000774.htm'
  ]
};

RX_BODY['copper-containing-device'] = {
  what: {
    ar: 'اللولب النحاسي إطار بلاستيكي على شكل حرف تي ملفوف بسلك من النحاس، يركّبه مدرَّب داخل الرحم عبر عنقه، وله خيط رفيع يتدلّى في المهبل يُتحقّق به من بقائه في موضعه. وهو الوسيلة الوحيدة عالية الفعالية في هذه الصفحة التي لا تحتوي هرموناً إطلاقاً، فلا تغيّر هرمونات الجسم ولا تمنع الإباضة، وتبقى الدورة قائمة بطبيعتها. وهو وسيلة طويلة الأمد عكوسة، والخصوبة تعود فور إخراجه بلا فترة انتظار. ولا يحمي من العدوى المنقولة جنسياً ولا يُغني عن الواقي.',
    en: 'The copper coil is a T-shaped plastic frame wound with copper wire, fitted by a trained provider inside the womb through the cervix, with a fine thread hanging into the vagina by which its position is checked. It is the only highly effective method on this page that contains no hormone at all, so it does not alter the body’s hormones or prevent ovulation, and the cycle continues naturally. It is a long-acting reversible method, and fertility returns the moment it is removed with no waiting period. It gives no protection against sexually transmitted infection and does not replace a condom.'
  },
  why: {
    ar: 'يُستعمل لمنع الحمل مدّة طويلة، ويناسب خاصة من لا تريد الهرمونات أو لا تصلح لها، ومن تريد أن تبقى دورتها الطبيعية على حالها. ويبدأ عمله من لحظة تركيبه لا بعد أيام، وهذه خاصية عملية مهمّة. ويُستعمل كذلك وسيلةً إسعافية بعد علاقة غير محميّة إذا رُكّب في المهلة التي يحدّدها مقدّم الرعاية، وهو من أعلى الوسائل الإسعافية فعاليةً. وخصوبة المرأة تعود مباشرةً بعد إخراجه بلا فترة انتظار.',
    en: 'It is used to prevent pregnancy for a long period, and suits in particular a woman who does not want hormones or cannot have them, and one who wants her natural cycle left as it is. It starts working from the moment it is fitted rather than days later, which is an important practical property. It is also used as an emergency method after unprotected intercourse if fitted within the window set by the provider, and it is among the most effective emergency options. Fertility returns straight after removal with no waiting period.'
  },
  how: {
    ar: 'يُطلق النحاس أيوناته باستمرار داخل تجويف الرحم، فتغيّر البيئة هناك وتصير معادية للحيوانات المنوية: تعرقل حركتها وانتقالها وتُضعف قدرتها على تلقيح البويضة. وقد يمنع أيضاً غرس البويضة الملقّحة في الجدار. فالمنع إذن يقع قبل التلقيح في أغلبه، وسببه كيميائي موضعي لا هرموني. ومن هذا يُفهم لماذا لا تتأثّر حمايته بالأدوية التي تُسرّع الكبد، ولماذا لا يُغيّر شيئاً في هرمونات الجسم ولا في الإباضة.',
    en: 'The copper continuously releases its ions inside the cavity of the womb, changing the environment there and making it hostile to sperm: it hinders their movement and transport and weakens their ability to fertilise the egg. It may also prevent a fertilised egg implanting in the wall. Prevention therefore happens mostly before fertilisation, and its cause is a local chemical one rather than hormonal. From this it is clear why its protection is not affected by medicines that speed the liver, and why it changes nothing in the body’s hormones or in ovulation.'
  },
  effects: {
    ar: 'أشهر آثاره أن الدورة تصير أغزر وأطول وأوجع، خصوصاً في الأشهر الأولى، مع تبقيع بين الدورات وألم ومغص. ومن ثمّ قد يجرّ نزفه الغزير إلى فقر دم بنقص الحديد عند بعض النساء، وهذا سبب يُتابع لا يُهمل. وتُذكر كذلك التهابات مهبلية، وألم عند الجماع، وخروج اللولب كاملاً أو جزئياً — وخروجه يعني زوال الحماية دون أن تشعر صاحبته. وكثير من هذه الآثار يخفّ مع مرور الأشهر الأولى، لكن غزارة الدورة قد تبقى ما دام اللولب في مكانه.',
    en: 'Its best known effects are that periods become heavier, longer and more painful, especially in the first months, with spotting between periods, pain and cramping. Its heavy bleeding may in turn lead to iron deficiency anaemia in some women, which is a reason for follow-up rather than neglect. Also reported are vaginal infections, pain during intercourse, and complete or partial expulsion of the device, and expulsion means protection is gone without the user feeling it. Many of these effects ease as the first months pass, but the heaviness of periods may persist for as long as the device is in place.'
  },
  warning: {
    ar: 'اطلبي الطوارئ عند ألم حوضي شديد أو مفاجئ، أو حمّى وقشعريرة، أو إفراز مهبلي كريه الرائحة، فهذه علامات التهاب حوض قد يُتلف الأنابيب ويُورث عقماً أو حملاً خارج الرحم. وإن تأخّرت دورتك واشتبهت بحمل فاعرضي نفسك اليوم: الحمل واللولب في مكانه قد يكون خارج الرحم، وقد يؤدّي بقاء اللولب إلى إجهاض إنتاني وتسمّم دم. واذهبي فوراً عند نزف غزير جداً أو مطوّل، أو ألم أثناء الجماع، أو قروح تناسلية، أو إذا لم تعودي تحسّين الخيط أو صرت تحسّين اللولب نفسه، فقد يكون نزل أو اخترق الجدار.',
    en: 'Seek emergency care for severe or sudden pelvic pain, fever and chills, or foul-smelling vaginal discharge, as these are signs of pelvic infection that can damage the tubes and lead to infertility or ectopic pregnancy. If your period is late and you suspect pregnancy, be seen the same day: pregnancy with the device in place may be ectopic, and leaving the device in can lead to septic miscarriage and blood poisoning. Go immediately for very heavy or prolonged bleeding, pain during intercourse, genital sores, or if you can no longer feel the thread or can feel the device itself, as it may have slipped or perforated the wall.'
  },
  interact: {
    ar: 'ليس له تعارض دوائي يُذكر لأنه لا يحتوي هرموناً ولا يُبتلع، وهذه ميزة عملية لمن يأخذ أدوية تُسرّع إنزيمات الكبد كأدوية السلّ والصرع وعشبة سانت جون، إذ لا تُضعف تلك حمايته كما تُضعف الوسائل الهرمونية. لكن يُنتبه إلى أن مضادات الالتهاب غير الستيرويدية تُستعمل أحياناً لتخفيف ألم الدورة معه بمشورة الطبيب. وأخبري أي طبيب أو أخصائي أشعة أن عندك لولباً قبل أي إجراء داخل الرحم أو تصوير.',
    en: 'It has no notable drug interactions because it contains no hormone and is not swallowed, which is a practical advantage for anyone taking medicines that induce liver enzymes such as tuberculosis and epilepsy drugs and St John’s wort, since these do not weaken its protection as they weaken hormonal methods. Note that non-steroidal anti-inflammatory drugs are sometimes used with it to ease period pain, on a doctor’s advice. Tell any doctor or imaging specialist that you have a coil before any procedure inside the womb or any scan.'
  },
  avoid: {
    ar: 'لا يُركّب مع الحمل أو الشكّ فيه، ولا مع تشوّه في تجويف الرحم يمنع استقراره، ولا مع التهاب حوض قائم، ولا بعد التهاب بطانة الرحم التالي للولادة أو الإجهاض إلا بعد مدّة يحدّدها الطبيب، ولا مع اشتباه سرطان في الرحم أو عنقه، ولا مع نزف مهبلي غير مفسَّر، ولا مع عدوى تناسلية غير معالَجة. ويُمنع خاصةً مع داء ويلسون ومع الحساسية للنحاس. ومن دورتها غزيرة أصلاً أو عندها فقر دم قد لا يكون هذا خيارها الأنسب. وخطر ثقب الجدار أعلى عند المرضعة.',
    en: 'It is not fitted with pregnancy or suspected pregnancy, nor with a distortion of the uterine cavity that prevents it sitting properly, nor with active pelvic infection, nor after inflammation of the womb lining following childbirth or miscarriage except after an interval set by the doctor, nor with suspected cancer of the womb or cervix, nor with unexplained vaginal bleeding, nor with an untreated genital infection. It is specifically contraindicated in Wilson disease and in copper allergy. A woman whose periods are already heavy or who is anaemic may find it is not her best choice. The risk of perforating the wall is higher in a breastfeeding mother.'
  },
  updated: '2026-09-10',
  src: [
    'https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=5ea7ce51-b87a-485e-b841-99466a07a4b2',
    'https://medlineplus.gov/ency/patientinstructions/000774.htm'
  ]
};

RX_BODY['condoms'] = {
  what: {
    ar: 'الواقي الذكري غلاف رقيق يُلبس على العضو المنتصب قبل الجماع فيمنع وصول المني إلى المهبل. أكثره من اللاتكس، ومنه أنواع من البولي يوريثان أو مطاط صناعي لمن عنده حساسية اللاتكس، ومنه نوع من غشاء طبيعي مسامّي يمنع الحمل لكنه أقلّ حماية من الفيروسات. ولأغلبه طرف مستودع يتجمّع فيه المني. ويُباع بلا وصفة في الصيدليات والمتاجر، وهو أرخص الوسائل وأيسرها حصولاً وأسرعها بدءاً، إذ لا يحتاج موعداً ولا فحصاً ولا قياساً ولا فترة انتظار قبل الاعتماد عليه.',
    en: 'A condom is a thin sheath worn over the erect penis before intercourse to stop semen reaching the vagina. Most are latex, some are polyurethane or synthetic rubber for anyone allergic to latex, and one type is a porous natural membrane that prevents pregnancy but protects less well against viruses. Most have a reservoir tip where the semen collects. It is sold without prescription in pharmacies and shops, and is the cheapest, most easily obtained and fastest to start of all the methods, since it needs no appointment, no examination, no sizing and no waiting period before it can be relied on.'
  },
  why: {
    ar: 'يُستعمل لغرضين معاً: منع الحمل، والوقاية من العدوى المنقولة جنسياً — وهذه الثانية هي ما ينفرد به عن كل الوسائل الأخرى في هذه الصفحة. فهو يقلّل انتقال ما ينتقل بالإفرازات كفيروس نقص المناعة والسيلان والكلاميديا والتهاب الكبد ب، ويقلّل ما ينتقل بملامسة الأغشية كالهربس والزهري وفيروس الورم الحليمي بقدر ما يغطّيه فعلاً. ولهذا يُنصح باستعماله مع وسيلة أخرى حين تكون الوقاية من العدوى مطلوبة أيضاً.',
    en: 'It is used for two purposes at once: preventing pregnancy, and protecting against sexually transmitted infection, and this second is what sets it apart from every other method on this page. It reduces the transmission of what spreads through secretions, such as HIV, gonorrhoea, chlamydia and hepatitis B, and reduces what spreads by mucosal contact, such as herpes, syphilis and human papillomavirus, to the extent of what it actually covers. This is why it is advised alongside another method whenever protection from infection is also needed.'
  },
  how: {
    ar: 'عمله ميكانيكي بحت: حاجز مادي يمنع اختلاط المني بإفرازات الطرف الآخر، ويمنع كذلك التماس المباشر بين الجلد والأغشية في المساحة التي يغطّيها. ولذلك تعتمد حمايته كلّها على سلامته وعلى تغطيته الصحيحة، وليس فيه هرمون ولا أثر على الجسم ولا على الخصوبة، فأثره ينتهي بانتهاء اللقاء. ومن هذا يُفهم أن ما يُضعف مادّته أو يُزحزحه أو يُمزّقه هو خطره الوحيد، ولا شأن له بالكبد ولا بالدم ولا بالدورة.',
    en: 'Its action is purely mechanical: a physical barrier that stops semen mixing with the other partner’s secretions, and also stops direct contact between skin and mucous membranes over the area it covers. All its protection therefore depends on it being intact and correctly covering. It contains no hormone and has no effect on the body or on fertility, and its effect ends when the encounter ends. From this it follows that whatever weakens its material, displaces it or tears it is its only danger; it has nothing to do with the liver, the blood or the cycle.'
  },
  effects: {
    ar: 'لا آثار جانبية جهازية له لأنه لا يدخل الجسم شيء منه. وأكثر ما يُشتكى منه تهيّج أو حكّة أو احمرار موضعي، وقد يكون سببه حساسية اللاتكس عند أحد الطرفين أو مبيد النطاف المدهون على بعض الأنواع. ومن كان عنده حساسية لاتكس فله البولي يوريثان أو المطاط الصناعي بديلاً. والنوع المدهون بمبيد النطاف لا يزيد الحماية من الحمل زيادة معتبرة، بل قد يزيد التهيّج. وقد يقلّ الإحساس عند البعض، وهذا شكوى شائعة لا ضرر فيها.',
    en: 'It has no systemic side effects because nothing of it enters the body. What is complained of most is local irritation, itching or redness, which may come from latex allergy in either partner or from the spermicide coating some types. Anyone with a latex allergy has polyurethane or synthetic rubber as an alternative. The spermicide-coated type does not add worthwhile protection against pregnancy and may increase irritation. Some people find sensation is reduced, which is a common complaint but a harmless one.'
  },
  warning: {
    ar: 'إذا انقطع الواقي أو انزلق أو اكتشفت بعد الجماع أنه لم يكن سليماً، فهذه حالة تُعالج بسرعة لا بانتظار: راجعي أو راجع مقدّم الرعاية في أقرب وقت لمناقشة المنع الإسعافي للحمل والوقاية من العدوى، فمهلة هذه الخيارات قصيرة وتضيق بالتأخير. واطلب الرعاية العاجلة عند تورّم الوجه أو الشفتين أو اللسان أو ضيق نفس بعد استعماله، فقد تكون حساسية شديدة من اللاتكس. واعرض أي قرحة تناسلية أو إفراز جديد أو حرقان بول بعد لقاء غير محمي على طبيب، ولا تنتظر زوالها من نفسها.',
    en: 'If the condom breaks or slips, or you discover after intercourse that it was not intact, this is a situation to act on quickly rather than wait out: see a healthcare provider as soon as possible to discuss emergency contraception and infection prevention, because the window for these options is short and narrows with delay. Seek urgent care for swelling of the face, lips or tongue or breathlessness after use, as this may be a severe latex allergy. Show any genital sore, new discharge or burning on passing urine after an unprotected encounter to a doctor, and do not wait for it to go on its own.'
  },
  interact: {
    ar: 'أهمّ تعارض عملي له ليس مع دواء يُبتلع بل مع ما يُدهن معه: الزيوت والمزلّقات الزيتية تُفسد اللاتكس وتُضعف الغلاف حتى ينقطع، فتُستعمل المزلّقات المائية بدلها. وكذلك بعض التحاميل والكريمات المهبلية المضادة للفطريات تُتلف اللاتكس فتُبطل حمايته أياماً بعد انتهاء العلاج — فيُستعمل بديل في تلك المدّة أو نوع غير لاتكسي. ولبس واقيين فوق بعضهما لا يزيد الأمان بل يزيد احتمال التمزّق، وهذه فكرة شائعة خاطئة.',
    en: 'Its most important practical interaction is not with a swallowed medicine but with what is applied alongside it: oils and oil-based lubricants damage latex and weaken the sheath until it tears, so water-based lubricants are used instead. Likewise some vaginal antifungal creams and pessaries damage latex and cancel its protection for days after treatment ends, so an alternative or a non-latex type is used during that period. Wearing two condoms one over the other does not add safety but increases the chance of tearing, and this is a widespread mistaken idea.'
  },
  avoid: {
    ar: 'لا يستعمله من عنده حساسية مثبتة للاتكس ولا شريكه، وله بدائل من البولي يوريثان أو المطاط الصناعي تؤدّي الغرضين معاً. وأما النوع المصنوع من الغشاء الطبيعي فلا يُعتمد عليه لمن يريد الوقاية من العدوى لأنه مسامّ. ولا يُستعمل واق مرّ عليه تاريخ صلاحيته أو مزّقت عبوته أو خُزّن في مكان حارّ أو في محفظة الجيب مدّة طويلة. وليس فيه ما يمنع استعماله في الحمل ولا في الرضاعة ولا مع أي مرض، وهذا من أوسع فوائده.',
    en: 'It is not used by anyone with a proven latex allergy, nor by their partner, and there are polyurethane or synthetic rubber alternatives that serve both purposes. The natural membrane type is not relied on by anyone wanting protection from infection, because it is porous. A condom past its expiry date, with a torn wrapper, or stored somewhere hot or kept a long time in a wallet is not used. There is nothing preventing its use in pregnancy, in breastfeeding or with any illness, and that is among its widest advantages.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK470385/',
    'https://medlineplus.gov/ency/article/001946.htm'
  ]
};

RX_BODY['diaphragms'] = {
  what: {
    ar: 'العازل المهبلي كأس مرن من المطاط أو السيليكون تضعه المرأة في مهبلها قبل الجماع فيغطّي عنق الرحم. لا يُستعمل وحده بل يُملأ بكريم أو هلام مبيد للنطاف قبل وضعه، فالحماية من الاثنين معاً لا من الكأس وحده. ومقاسه ونوعه يحدّدهما مقدّم الرعاية بفحص، إذ لا يصلح مقاس واحد للجميع. وهو وسيلة تُتحكّم فيها المرأة بنفسها وتُخرجها متى شاءت بعد المدّة التي يحدّدها مقدّم الرعاية، ولا يحتاج إلى موعد عيادة عند كل استعمال. وهو قابل للغسل وإعادة الاستعمال.',
    en: 'A diaphragm is a flexible cup of rubber or silicone that the woman places in her vagina before intercourse so it covers the cervix. It is not used alone but is filled with a spermicidal cream or jelly before insertion, so protection comes from the two together rather than from the cup by itself. Its size and type are decided by a healthcare provider after an examination, since one size does not fit everyone. It is a method the woman controls herself and removes when she wishes after the interval her provider specifies, and it needs no clinic appointment at each use. It can be washed and used again.'
  },
  why: {
    ar: 'يُستعمل لمنع الحمل عند من تريد وسيلة خالية من الهرمونات تماماً، وتُستعمل عند الحاجة فقط لا كل يوم، ويمكن إيقافها في أي وقت بلا انتظار عودة خصوبة. ويناسب من لا تصلح لها الوسائل الهرمونية أو لا ترغب فيها، ومن لا تريد شيئاً مركّباً داخل الرحم. لكن فعاليته أقلّ بوضوح من اللوالب والشرائح، وحمله على الاستعمال الصحيح في كل مرّة هو ما يفرّق بين رقم ورقم. ولا يقي من العدوى المنقولة جنسياً.',
    en: 'It is used to prevent pregnancy by a woman who wants a method completely free of hormones, used only when needed rather than every day, and stoppable at any moment with no wait for fertility to return. It suits someone for whom hormonal methods are unsuitable or unwanted, and someone who does not want anything fitted inside the womb. But it is clearly less effective than coils and implants, and using it correctly every single time is what separates one outcome from another. It gives no protection against sexually transmitted infection.'
  },
  how: {
    ar: 'عمله مزدوج. الجزء الأول ميكانيكي: الكأس يجلس فوق عنق الرحم فيقف حاجزاً في وجه الحيوانات المنوية ويمنعها من دخول الرحم. والجزء الثاني كيميائي: مبيد النطاف الموضوع داخله وحوله يقتل ما التفّ حول حافّته أو تسرّب من جنبه. ولذلك لا يُوضع فارغاً ولا يُخرج قبل انقضاء المدّة التي يحدّدها مقدّم الرعاية بعد آخر جماع، لأن الحيوانات المنوية تبقى حيّة مدّة بعده. وليس فيه هرمون ولا أثر جهازي على الجسم.',
    en: 'Its action is twofold. The first part is mechanical: the cup sits over the cervix and stands as a barrier in the way of the sperm, keeping them out of the womb. The second is chemical: the spermicide placed inside and around it kills whatever gets around its rim or slips past its edge. That is why it is not inserted empty and not removed before the interval the provider specifies after the last intercourse, because sperm stay alive for a while afterwards. It contains no hormone and has no systemic effect on the body.'
  },
  effects: {
    ar: 'أكثر ما يُذكر معه تهيّج موضعي أو حكّة أو حرقان، وأغلبه من مبيد النطاف لا من الكأس نفسه، وقد يصيب الطرفين. ويزيد معه احتمال التهابات المسالك البولية المتكرّرة، ويُذكر كذلك التهاب المهبل البكتيري والفطري. وقد تشعر المرأة بضغط أو انزعاج إذا كان المقاس غير مناسب، وهذا سبب لإعادة القياس لا لاحتماله. وحساسية اللاتكس واردة عند من عنده استعداد لها، ولها بدائل من السيليكون.',
    en: 'What is mentioned most with it is local irritation, itching or burning, most of it from the spermicide rather than the cup itself, and it can affect either partner. It raises the likelihood of recurrent urinary tract infections, and bacterial and fungal vaginitis are also reported. A woman may feel pressure or discomfort if the size is wrong, and that is a reason to be re-measured rather than to put up with it. Latex allergy is possible in anyone predisposed, and silicone alternatives exist.'
  },
  warning: {
    ar: 'اطلبي الطوارئ فوراً عند حمّى مرتفعة مفاجئة مع قيء أو إسهال وطفح يشبه حروق الشمس ودوخة أو هبوط، فهذه علامات متلازمة الصدمة السمّية، وهي نادرة لكنها مرتبطة بترك العازل داخل المهبل أطول ممّا يجب. واذهبي للطبيب عند حرقان بول أو إلحاح أو ألم أسفل البطن، فهي علامات التهاب مسالك يتكرّر مع هذه الوسيلة. واعرضي أي إفراز كريه الرائحة أو حكّة شديدة أو تقرّح. وإن انزلق العازل أو خرج أثناء الجماع أو نسيتِ مبيد النطاف فناقشي المنع الإسعافي للحمل بسرعة.',
    en: 'Get emergency help at once for a sudden high fever with vomiting or diarrhoea, a rash like sunburn, and dizziness or collapse, as these are signs of toxic shock syndrome, which is rare but linked to leaving the diaphragm in the vagina longer than it should be. See a doctor for burning on passing urine, urgency, or lower abdominal pain, which are signs of the urinary infection that recurs with this method. Show any foul-smelling discharge, severe itching or ulceration. And if the diaphragm slips or comes out during intercourse, or you forgot the spermicide, discuss emergency contraception quickly.'
  },
  interact: {
    ar: 'أهمّ ما يُنتبه له أن الزيوت والمزلّقات الزيتية وبعض الكريمات والتحاميل المهبلية — ومنها مضادات الفطريات — تُتلف مطاط العازل وتُضعفه فيفقد حمايته، ويمتدّ هذا الإضعاف أياماً بعد انتهاء العلاج، فتُستعمل وسيلة أخرى في تلك المدّة. وتُستعمل المزلّقات المائية لا الزيتية معه. وليس بينه وبين الأدوية المبتلعة تعارض يُذكر لأنه لا يدخل الدم. ومن كان عنده التهاب مسالك متكرّر فليناقش مبيد النطاف نفسه مع طبيبه، فقد يكون هو السبب.',
    en: 'The main thing to watch is that oils, oil-based lubricants and some vaginal creams and pessaries, including antifungals, damage the rubber of the diaphragm and weaken it so it loses its protection, and this weakening extends for days after treatment ends, so another method is used in that period. Water-based, not oil-based, lubricants are used with it. There is no notable interaction with swallowed medicines because it does not enter the bloodstream. Anyone with recurrent urinary infections should discuss the spermicide itself with their doctor, as it may be the cause.'
  },
  avoid: {
    ar: 'لا يُستعمل قبل قياسه عند مقدّم الرعاية، ويُعاد القياس بعد الولادة أو الإجهاض أو تغيّر كبير في الوزن لأن المقاس القديم قد لا يعود صالحاً. ولا تستعمله من عندها حساسية للاتكس أو لمبيد النطاف، وللأولى بديل سيليكوني. ويُتجنّب عند التهاب مهبلي أو حوضي قائم، وعند تشوّه أو هبوط يمنع جلوسه على عنق الرحم، وفي فترة النزف. ومن سبقت لها متلازمة الصدمة السمّية لا تستعمله. ومن يحتاج وقاية من العدوى المنقولة جنسياً يحتاج الواقي معه، فالعازل لا يقي منها.',
    en: 'It is not used before being sized by a healthcare provider, and is re-sized after childbirth, miscarriage or a large change in weight, because the old size may no longer fit. It is not used by anyone allergic to latex or to the spermicide, and for the first there is a silicone alternative. It is avoided during active vaginal or pelvic infection, with any distortion or prolapse that stops it sitting on the cervix, and during bleeding. Anyone who has had toxic shock syndrome does not use it. And anyone needing protection from sexually transmitted infection needs a condom with it, because the diaphragm does not provide it.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/ency/article/001946.htm',
    'https://www.ncbi.nlm.nih.gov/books/NBK279148/'
  ]
};

RX_BODY['progesterone-vaginal-ring'] = {
  what: {
    ar: 'حلقة البروجستيرون المهبلية حلقة سيليكون طريّة مرنة تحتوي بروجستيروناً طبيعياً مطحوناً يخرج منها ببطء ثابت. تضعها المرأة في مهبلها بنفسها وتخرجها بنفسها بلا حاجة إلى عيادة، وتُبدَّل بأخرى بعد المدّة التي يحدّدها مقدّم الرعاية. صُمّمت خصّيصاً للمرضعة، وسُجّلت في عدد من بلدان أمريكا اللاتينية وليست متوفّرة في كل مكان، فقد لا تجدينها في صيدلية بلدك. وهي وسيلة تُتحكّم فيها المرأة بنفسها. ولا تحمي من العدوى المنقولة جنسياً.',
    en: 'The progesterone vaginal ring is a soft flexible silicone ring containing micronised natural progesterone that leaves it at a slow steady rate. The woman inserts and removes it herself with no need for a clinic, and it is replaced with another after the interval her provider specifies. It was designed specifically for the breastfeeding mother, and is registered in a number of Latin American countries rather than being available everywhere, so it may not be found in your local pharmacy. It is a method the woman controls herself. It gives no protection against sexually transmitted infection.'
  },
  why: {
    ar: 'تُستعمل لمنع الحمل عند المرضعة تحديداً، ابتداءً من الأسابيع الأولى بعد الولادة وما دامت الرضاعة قائمة. وفكرتها أنها تسند الحماية الطبيعية التي تمنحها الرضاعة بدل أن تُتركا وحدهما، فالمرأة التي ترضع ليست في أمان تامّ من الحمل. وميزتها التي بُنيت عليها أنها لا تُنقص الحليب ولا تؤثّر في نموّ الرضيع ولا في وزنه، وقد رُصد أنها تطيل انقطاع الطمث المصاحب للرضاعة مقارنةً باللولب النحاسي.',
    en: 'It is used for contraception in the breastfeeding mother specifically, starting from the first weeks after birth and for as long as breastfeeding continues. Its idea is to back up the natural protection that lactation gives rather than leave that alone, because a woman who is breastfeeding is not entirely safe from pregnancy. The advantage it was built on is that it does not reduce the milk or affect the infant’s growth or weight, and it has been observed to prolong the absence of periods that accompanies breastfeeding compared with the copper coil.'
  },
  how: {
    ar: 'يخرج البروجستيرون من الحلقة داخل المهبل ويُمتصّ موضعياً، فيدعم استجابة هرمون البرولاكتين للرضاعة ويُبقي كبح الإباضة قائماً. أي أنه لا يعاكس آلية الرضاعة بل يقوّيها: الرضاعة نفسها تكبح الإباضة، والحلقة تُثبّت هذا الكبح وتمدّه فلا ينقطع بين رضعة وأخرى. ولأن البروجستيرون هنا هو الهرمون الطبيعي نفسه لا مركّباً صناعياً، فما يصل منه إلى الحليب قليل ولا يُتوقّع له أثر في الرضيع.',
    en: 'Progesterone leaves the ring inside the vagina and is absorbed locally, supporting the prolactin response to breastfeeding and keeping ovulation suppressed. That is, it does not work against the mechanism of lactation but strengthens it: breastfeeding itself suppresses ovulation, and the ring steadies and extends that suppression so it does not lapse between one feed and the next. Because the progesterone here is the natural hormone itself rather than a synthetic compound, little of it reaches the milk and no effect is expected in the infant.'
  },
  effects: {
    ar: 'أكثر ما سُجّل معها في الدراسات إفراز مهبلي، واضطراب في نمط النزف يشمل غزارة الطمث، وأغلب ما وُصف كان خفيفاً أو متوسّطاً. واضطراب النزف أثر معروف في كل الوسائل البروجستينية وهو أشيع أسباب تركها. وأشهر مشكلة عملية معها ليست جانبية بل ميكانيكية: خروج الحلقة من مكانها، وأكثره في الأشهر الأولى وعند القرفصاء، وقد يمرّ دون أن تنتبه المرأة فتسقط الحماية. ولم تُرصد آثار ضارّة على الرضاعة ولا على صحّة الرضيع.',
    en: 'What was recorded with it most in studies is vaginal discharge and a disturbance of the bleeding pattern including heavy periods, and most of what was described was mild or moderate. Bleeding disturbance is a known effect of every progestogen method and is the commonest reason for stopping. The best known practical problem with it is not a side effect but a mechanical one: the ring coming out of place, mostly in the first months and while squatting, and it can pass unnoticed so that protection lapses. No harmful effects on breastfeeding or on the infant’s health were observed.'
  },
  warning: {
    ar: 'إذا خرجت الحلقة ولم تجديها، أو خرجت وبقيت خارج المهبل مدّة، فالحماية قد سقطت: استعملي وسيلة أخرى واتّصلي بمقدّم الرعاية سريعاً لتدبير البديل ومناقشة المنع الإسعافي إن لزم. واذهبي للطبيب عند نزف مهبلي غزير أو متطاول أو مختلف عن المعتاد، وعند إفراز كريه الرائحة أو حكّة شديدة أو ألم أو حمّى، فهذه علامات عدوى لا تُترك. وأي ألم حوضي شديد أو تأخّر دورة مع اشتباه حمل يُعرض في يومه. وتوقّفي واطلبي الرعاية عند تورّم الوجه أو ضيق نفس.',
    en: 'If the ring comes out and you cannot find it, or comes out and stays out for a while, protection has lapsed: use another method and contact your provider quickly to arrange a replacement and discuss emergency contraception if needed. See a doctor for heavy, prolonged or unusual vaginal bleeding, and for foul-smelling discharge, severe itching, pain or fever, as these are signs of infection that must not be left. Any severe pelvic pain, or a late period with suspected pregnancy, is to be seen the same day. Stop and seek care for swelling of the face or breathlessness.'
  },
  interact: {
    ar: 'لأن الهرمون يُمتصّ من المهبل مباشرةً ولا يمرّ على الكبد كما يمرّ القرص المبتلع، فالتعارضات المعروفة أقلّ ممّا هي مع الحبوب. ومع ذلك تُناقَش مع الطبيب الأدوية المحرّضة لإنزيمات الكبد كأدوية السلّ والصرع وعشبة سانت جون قبل الاعتماد عليها وحدها. والأهمّ عملياً ما يوضع في المهبل معها: الكريمات والتحاميل المهبلية قد تغيّر امتصاصها أو تُزحزحها، فتُسأل عنها الصيدلية قبل الجمع. وأخبري من يصف لك دواءً جديداً أنك ترضعين وتستعملين حلقة.',
    en: 'Because the hormone is absorbed directly from the vagina and does not pass through the liver the way a swallowed tablet does, known interactions are fewer than with pills. Even so, medicines that induce liver enzymes, such as tuberculosis and epilepsy drugs and St John’s wort, should be discussed with the doctor before relying on it alone. More important in practice is what is placed in the vagina alongside it: vaginal creams and pessaries may change its absorption or displace it, so ask the pharmacy before combining. And tell anyone prescribing you something new that you are breastfeeding and using a ring.'
  },
  avoid: {
    ar: 'ليست وسيلة لكل امرأة بل صُمّمت للمرضعة في الفترة التالية للولادة، فمن انقطعت رضاعتها احتاجت وسيلة أخرى. ولا تُستعمل مع الحمل أو الشكّ فيه، ولا مع نزف مهبلي غير مفسَّر قبل معرفة سببه، ولا مع التهاب مهبلي أو حوضي قائم حتى يُعالَج، ولا مع الحساسية لأي من مكوّناتها. وتُناقش مع الطبيب قبل استعمالها إن كان عندك مرض كبدي أو سرطان معتمد على الهرمونات. ومن يحتاج وقاية من العدوى المنقولة جنسياً يحتاج الواقي معها.',
    en: 'It is not a method for every woman but was designed for the breastfeeding mother in the period after birth, so a woman whose breastfeeding has ended needs another method. It is not used with pregnancy or suspected pregnancy, nor with unexplained vaginal bleeding before its cause is known, nor with an active vaginal or pelvic infection until that is treated, nor with allergy to any of its components. Discuss it with a doctor first if you have liver disease or a hormone-dependent cancer. Anyone needing protection from sexually transmitted infection needs a condom alongside it.'
  },
  updated: '2026-09-10',
  src: [
    'https://pmc.ncbi.nlm.nih.gov/articles/PMC7483628/',
    'https://www.ncbi.nlm.nih.gov/books/NBK501345/'
  ]
};

RX_BODY['clomifene'] = {
  what: {
    ar: 'الكلوميفين قرص يُبتلع، ينتمي إلى فصيلة تُسمّى المعدّلات الانتقائية لمستقبل الإستروجين، أي أنه يرتبط بمستقبلات هرمون الإستروجين في أعضاء مختلفة فيتصرّف في بعضها تصرّف الإستروجين وفي بعضها تصرّف المعاكس له. وهو من أقدم منشّطات الإباضة وأوسعها استعمالاً، ويُصرف بوصفة ومتابعة لأن استعماله مرتبط بمواعيد الدورة وبفحوص يجريها الطبيب، لا بابتلاعه متى شاءت صاحبته.',
    en: 'Clomifene is a swallowed tablet belonging to a class called selective oestrogen receptor modulators, meaning it binds to oestrogen receptors in different organs and behaves in some like oestrogen and in others like its opposite. It is among the oldest and most widely used ovulation stimulants, and is dispensed on prescription with follow-up, because its use is tied to the timing of the cycle and to tests the doctor performs, not simply to swallowing it whenever the woman chooses.'
  },
  why: {
    ar: 'يُوصف لتحفيز الإباضة عند المرأة التي لا تبيّض أو تبيّض متقطّعاً وتريد الحمل، وأشهر أسباب ذلك تكيّس المبايض. ويُستعمل كذلك في بعض صور غياب الطمث الثانوي: ما يلي إيقاف حبوب منع الحمل، وما يصحب ارتفاع البرولاكتين مع إفراز الحليب، وما سببه نفسي. وله استعمال في عقم الرجل وفي قصور الغدد التناسلية الثانوي. وهو لا يعالج سبب العقم بل يفتح نافذة إباضة، ولذلك يُحدَّد عدد الدورات التي يُجرَّب فيها ولا يُكرَّر بلا نهاية.',
    en: 'It is prescribed to stimulate ovulation in a woman who does not ovulate or ovulates only intermittently and wants to conceive, the commonest cause being polycystic ovary syndrome. It is also used in some forms of secondary absence of periods: after stopping the contraceptive pill, alongside raised prolactin with milk discharge, and where the cause is psychological. It has a use in male infertility and in secondary hypogonadism. It does not treat the cause of infertility but opens a window for ovulation, which is why the number of cycles it is tried for is limited and it is not repeated endlessly.'
  },
  how: {
    ar: 'يرتبط الكلوميفين بمستقبلات الإستروجين في الوطاء والغدة النخامية فيحجب عنهما إشارة الإستروجين، فيظنّ الجسم أن مستواه منخفض. وردّ الفعل أن النخامية تزيد إفراز الهرمونين المنبّه للجُريب والمُلَوتِن، وهما اللذان يدفعان الجُريب في المبيض إلى النموّ والنضج ثم الانفجار وإطلاق البويضة. لكنه يرتبط أيضاً بمستقبلات في عنق الرحم وبطانته، فقد يُثخّن المخاط ويرقّق البطانة، وهذا وجه من أوجه قصوره رغم نجاح التحفيز.',
    en: 'Clomifene binds to oestrogen receptors in the hypothalamus and the pituitary and blocks the oestrogen signal from reaching them, so the body believes its level is low. The response is that the pituitary increases its release of follicle-stimulating and luteinising hormone, and these push the follicle in the ovary to grow and mature, then rupture and release the egg. But it also binds to receptors in the cervix and the womb lining, so it may thicken the mucus and thin the lining, and that is one of its shortcomings even when the stimulation succeeds.'
  },
  effects: {
    ar: 'أكثر ما يُذكر معه هبّات الحرارة والاحمرار الوعائي، والصداع، والدوخة، والغثيان والقيء، وشدّ الثديين وإيلامهما، وانتفاخ البطن، ونزف مهبلي غير معتاد. ويُذكر كذلك تقلّب المزاج واحتمال اشتداد مرض نفسي قائم. ومن آثاره التي يجب أن تُعرف قبل البدء لا بعده: ارتفاع واضح في احتمال الحمل بأكثر من جنين، وهذا ليس أثراً جانبياً هيّناً بل قرار يُناقَش. وأشيع أسباب إيقافه اضطراب البصر ومتلازمة فرط تنبيه المبيض.',
    en: 'What is reported with it most is hot flushes and vasomotor flushing, headache, dizziness, nausea and vomiting, tight and tender breasts, abdominal bloating and unusual vaginal bleeding. Mood swings and the possible worsening of an existing psychiatric illness are also described. Among its effects that must be known before starting rather than after: a clear rise in the chance of conceiving more than one baby, and this is not a trivial side effect but a decision to be discussed. The commonest reasons for stopping it are visual disturbance and ovarian hyperstimulation syndrome.'
  },
  warning: {
    ar: 'أوقفي الدواء واتّصلي بطبيبك فوراً عند أي اضطراب في البصر: تشوّش، أو ازدواج، أو بقع أو ومضات، فهذه توجب الإيقاف وفحص العين العاجل. واطلبي الطوارئ عند ألم أو انتفاخ شديد في البطن، أو زيادة وزن سريعة، أو غثيان وقيء لا يهدأ، أو ضيق نفس، أو قلّة بول — فهذه علامات فرط تنبيه المبيض، وقد تتفاقم خلال يوم واحد إلى حالة طارئة. واذهبي فوراً عند نزف مهبلي غزير أو ألم حوضي حادّ مفاجئ. ولا تقودي إن تغيّر بصرك. وأخبري طبيبك بأي تدهور نفسي أو أفكار مؤذية.',
    en: 'Stop the medicine and call your doctor at once for any disturbance of vision: blurring, double vision, spots or flashes, as these require stopping and an urgent eye examination. Seek emergency help for severe abdominal pain or swelling, rapid weight gain, nausea and vomiting that will not settle, breathlessness, or passing little urine, as these are signs of ovarian hyperstimulation, which can worsen within a single day into an emergency. Go immediately for heavy vaginal bleeding or sudden severe pelvic pain. Do not drive if your vision changes. And tell your doctor of any psychiatric deterioration or harmful thoughts.'
  },
  interact: {
    ar: 'أخبري طبيبك وصيدليّك بكل ما تأخذينه من أدوية بوصفة أو بدونها ومن مكمّلات وأعشاب قبل البدء، فبعضها يحتاج تعديلاً أو متابعة. ويُنتبه بخاصّة إلى الجمع بينه وبين منشّطات إباضة أخرى أو حقن الغدد التناسلية، فهذا يرفع احتمال فرط تنبيه المبيض والحمل المتعدّد ولا يُفعل إلا تحت إشراف. ومستحضرات الإستروجين تعاكس مقصده. وأدوية الاضطراب النفسي تُذكر لأنها قد تتداخل مع تقلّبات المزاج التي يسبّبها. والقاعدة: لا يُضاف عليه شيء بلا علم واصفه.',
    en: 'Tell your doctor and pharmacist everything you take, prescribed or not, including supplements and herbs, before starting, as some need adjustment or monitoring. Particular care is needed when combining it with other ovulation stimulants or gonadotrophin injections, since this raises the chance of ovarian hyperstimulation and multiple pregnancy and is done only under supervision. Oestrogen-containing preparations work against its purpose. Psychiatric medicines should be mentioned because they may interact with the mood swings it causes. The rule is that nothing is added to it without the knowledge of the person who prescribed it.'
  },
  avoid: {
    ar: 'لا يُؤخذ في الحمل ولا عند الشكّ فيه ولا في الرضاعة، ويُجرى اختبار حمل قبل البدء وبين الدورات. ويُمنع مع مرض الكبد، ومع نزف رحمي غير مشخَّص، ومع خلل غير مضبوط في الغدة الدرقية أو الكظر، ومع أورام الغدة النخامية، ومع كيسات المبيض التي ليست من تكيّس المبايض، ومع سرطان بطانة الرحم. ويُتجنّب مع الأورام الليفية الرحمية إلا بمشورة. ولا يُطال استعماله لأن الاستعمال المطوّل ارتبط باحتمال سرطان المبيض. ولا يُعطى لتنشيط الأداء الرياضي.',
    en: 'It is not taken in pregnancy, when pregnancy is suspected, or while breastfeeding, and a pregnancy test is done before starting and between cycles. It is contraindicated with liver disease, undiagnosed uterine bleeding, uncontrolled thyroid or adrenal disorder, pituitary tumours, ovarian cysts not due to polycystic ovary syndrome, and cancer of the womb lining. It is avoided with uterine fibroids except on advice. Its use is not prolonged, because prolonged use has been linked to a possible risk of ovarian cancer. And it is not given to enhance athletic performance.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682704.html',
    'https://www.ncbi.nlm.nih.gov/books/NBK559292/'
  ]
};

RX_BODY['letrozole'] = {
  what: {
    ar: 'الليتروزول قرص يُبتلع من فصيلة مثبّطات الأروماتاز غير الستيرويدية. والأروماتاز إنزيم يحوّل الأندروجينات إلى إستروجين، فتثبيطه يُنقص كمية الإستروجين التي يصنعها الجسم. صُنع أصلاً لسرطان الثدي بعد سنّ اليأس وهو ترخيصه الرسمي، ثم اتّسع استعماله خارج الترخيص إلى تحفيز الإباضة حتى صار توصية أولى في تكيّس المبايض عند جمعيات طبّ الإنجاب. فهو دواء واحد بوجهين مختلفين تماماً في الغرض.',
    en: 'Letrozole is a swallowed tablet from the class of non-steroidal aromatase inhibitors. Aromatase is an enzyme that converts androgens into oestrogen, so inhibiting it reduces the amount of oestrogen the body makes. It was originally made for breast cancer after the menopause, which is its official licence, and its use later widened off-label to ovulation induction until it became a first-line recommendation in polycystic ovary syndrome among reproductive medicine societies. It is one medicine with two entirely different purposes.'
  },
  why: {
    ar: 'له استعمالان. الأول والمرخّص: سرطان الثدي المبكّر والمتقدّم عند من بلغت سنّ اليأس، سواء بعد الجراحة والإشعاع أو بعد التاموكسيفين، حيث يُحرم الورم من الإستروجين الذي يغذّيه. والثاني وهو خارج الترخيص في كثير من البلدان: تحفيز الإباضة عند من لا تبيّض وتريد الحمل، وخصوصاً في تكيّس المبايض، حيث أظهر إباضة وولادات حيّة أعلى من الكلوميفين واحتمال حمل متعدّد أقلّ. وفي هذا الاستعمال يوصف تحت متابعة طبيب خصوبة.',
    en: 'It has two uses. The first, and the licensed one, is early and advanced breast cancer in women past the menopause, whether after surgery and radiation or after tamoxifen, where the tumour is deprived of the oestrogen that feeds it. The second, off-label in many countries, is ovulation induction in a woman who does not ovulate and wants to conceive, particularly in polycystic ovary syndrome, where it has shown higher ovulation and live birth rates than clomifene with a lower chance of multiple pregnancy. In this use it is prescribed under the follow-up of a fertility doctor.'
  },
  how: {
    ar: 'يوقف الليتروزول عمل الأروماتاز فيهبط الإستروجين. وفي سرطان الثدي المعتمد على الهرمون، هذا الهبوط يجوّع خلايا الورم فيبطؤ نموّها أو يتوقّف. وفي تحفيز الإباضة، الهبوط نفسه يرفع الكبح الذي يفرضه الإستروجين على النخامية، فتزيد هذه من إفراز الهرمون المنبّه للجُريب فينمو الجُريب وتقع الإباضة. وفرقه عن الكلوميفين أنه لا يحجب مستقبلات الإستروجين في الرحم وعنقه، فتبقى البطانة والمخاط أصلح لحدوث الحمل. وعمره في الجسم قصير فلا يتراكم أثره بين دورة وأخرى.',
    en: 'Letrozole stops the action of aromatase, so oestrogen falls. In hormone-dependent breast cancer this fall starves the tumour cells so their growth slows or stops. In ovulation induction the same fall lifts the restraint oestrogen places on the pituitary, so it releases more follicle-stimulating hormone, the follicle grows and ovulation occurs. Its difference from clomifene is that it does not block oestrogen receptors in the womb and cervix, so the lining and the mucus stay more suitable for conception. Its life in the body is short, so its effect does not accumulate from one cycle to the next.'
  },
  effects: {
    ar: 'أكثر ما يُذكر معه هبّات الحرارة وتعرّق الليل، والغثيان والقيء، وألم المفاصل والعظام، والإرهاق، والصداع، والدوخة، وتساقط الشعر. وفي استعمال الخصوبة تكون الآثار أخفّ عادةً وعابرة: إرهاق ودوخة وصداع وانتفاخ وألم ظهر وانزعاج في الثدي، واحتمال فرط تنبيه المبيض منخفض في هذا السياق. وأثره الأثقل يظهر مع الاستعمال الطويل في السرطان: فهو قد يُحدث هشاشة العظام أو يزيدها ويرفع احتمال الكسور، ولذلك تُتابع العظام.',
    en: 'What is reported with it most is hot flushes and night sweats, nausea and vomiting, joint and bone pain, fatigue, headache, dizziness and hair loss. In fertility use the effects are usually milder and transient: tiredness, dizziness, headache, bloating, back pain and breast discomfort, and the chance of ovarian hyperstimulation is low in this setting. Its heavier effect appears with long use in cancer: it can cause or worsen thinning of the bones and raise the risk of fracture, which is why the bones are monitored.'
  },
  warning: {
    ar: 'اتّصلي بطبيبك فوراً عند ألم في الصدر أو صعوبة في التنفّس أو نزف غير معتاد. واطلبي الطوارئ عند صداع شديد مفاجئ، أو اضطراب مفاجئ في النطق، أو ضعف أو خدر في ذراع أو ساق، فهذه علامات تستوجب تقييماً عاجلاً. واذهبي فوراً عند اصفرار الجلد أو بياض العين. وتوقّفي واطلبي المساعدة عند طفح أو شرى أو تورّم. وفي استعمال الخصوبة: انتفاخ بطن شديد مع ألم وقيء وقلّة بول يستوجب الطوارئ. ولا تقودي حتى تعرفي أثره فيك، فقد يسبّب نعاساً ودوخة. وأي كسر بعد رضّة بسيطة يُبلَّغ.',
    en: 'Call your doctor at once for chest pain, difficulty breathing or unusual bleeding. Seek emergency help for a sudden severe headache, sudden difficulty with speech, or weakness or numbness in an arm or a leg, as these need urgent assessment. Go immediately if the skin or the whites of the eyes turn yellow. Stop and seek help for a rash, hives or swelling. In fertility use: severe abdominal swelling with pain, vomiting and passing little urine requires emergency care. Do not drive until you know its effect on you, as it can cause drowsiness and dizziness. And any fracture after a minor knock should be reported.'
  },
  interact: {
    ar: 'أخبري طبيبك وصيدليّك بكل ما تأخذينه من أدوية بوصفة أو بدونها ومن مكمّلات وأعشاب، فقد يحتاج بعضها تعديلاً. وأهمّ ما يُنتبه له مبدئياً أن أي مستحضر يحتوي إستروجيناً يعاكس مقصد الدواء كلّه، سواء في السرطان أو في تحفيز الإباضة. وفي سياق الخصوبة يُنتبه إلى الجمع بينه وبين منشّطات أخرى أو حقن الغدد التناسلية، فهذا يرفع احتمال فرط تنبيه المبيض والحمل المتعدّد ولا يُفعل إلا بإشراف. ولا يُضاف عليه شيء بلا علم واصفه.',
    en: 'Tell your doctor and pharmacist everything you take, prescribed or not, including supplements and herbs, as some may need adjustment. The most important thing to note from the outset is that any preparation containing oestrogen works against the whole purpose of the medicine, whether in cancer or in ovulation induction. In the fertility setting, care is needed when combining it with other stimulants or gonadotrophin injections, since this raises the chance of ovarian hyperstimulation and multiple pregnancy and is done only under supervision. Nothing is added to it without the knowledge of the prescriber.'
  },
  avoid: {
    ar: 'ترخيصه لسرطان الثدي مقصور على من بلغت سنّ اليأس، ولا يُؤخذ في الحمل لأنه قد يؤذي الجنين، ولا في الرضاعة. أما في تحفيز الإباضة فيُعطى في مرحلة محدّدة من الدورة قبل حدوث الحمل ثم يزول من الجسم بسرعة، وقد أظهرت مراجعات كبيرة أن نسب التشوّهات الخلقية في الحمل الذي جاء به مماثلة للطبيعي. ويحتاج حذراً ومتابعة من عندها هشاشة عظام أو عوامل خطر للكسور. ولا يُستعمل بلا تشخيص ولا يُشترى لتنشيط الخصوبة من تلقاء النفس، فهو خارج الترخيص في هذا الغرض.',
    en: 'Its licence in breast cancer is limited to women past the menopause, it is not taken in pregnancy because it may harm the fetus, and it is not taken while breastfeeding. In ovulation induction it is given at a defined stage of the cycle before conception and then clears from the body quickly, and large reviews have shown that rates of congenital malformation in pregnancies conceived with it are comparable to background rates. Caution and monitoring are needed for anyone with thinning bones or risk factors for fracture. It is not used without a diagnosis and is not bought to boost fertility on one’s own initiative, as it is off-label for that purpose.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a698004.html',
    'https://pmc.ncbi.nlm.nih.gov/articles/PMC12467464/'
  ]
};
